begin;
create table audit.events (id uuid primary key default gen_random_uuid(), occurred_at timestamptz not null default now(), request_id uuid, correlation_id uuid, actor_user_id uuid references auth.users(id) on delete set null, actor_name_snapshot text, actor_email_snapshot citext, actor_type text not null default 'user' check (actor_type in ('user','system','service','support_preview')), organization_id uuid references platform.organizations(id) on delete restrict, company_id uuid references platform.companies(id) on delete restrict, application_key text not null, page_key text, action_key text not null, outcome text not null default 'success' check (outcome in ('success','failure','denied')), entity_type text, entity_id uuid, entity_label text, summary text not null, before_data jsonb, after_data jsonb, changed_fields text[], ip_hash text, user_agent text, metadata jsonb not null default '{}');
create index audit_events_org_time on audit.events (organization_id, occurred_at desc);
create table audit.ui_events (id bigint generated always as identity primary key, occurred_at timestamptz not null default now(), session_id uuid not null, actor_user_id uuid references auth.users(id) on delete set null, organization_id uuid references platform.organizations(id) on delete cascade, company_id uuid references platform.companies(id) on delete cascade, application_key text not null, page_key text, event_name text not null, element_key text, properties jsonb not null default '{}');
create or replace function private.block_audit_mutation() returns trigger language plpgsql set search_path = pg_catalog as $$ begin raise exception 'audit events are immutable'; end; $$;
create trigger audit_events_immutable before update or delete on audit.events for each row execute function private.block_audit_mutation();
comment on table audit.ui_events is 'Allowlisted product analytics only; never store secrets, IDs, message bodies or raw form values.';
commit;
